116	    {
117	        var result = new List<IPNetwork2>();
118	        var queue = new Queue<IPNetwork2>();
119	        queue.Enqueue(this);
120	        
121	        while (queue.Count > 0)
122	        {
123	            var current = queue.Dequeue();
124	            
125	            // If current doesn't overlap with hole, add it to result
126	            if (!current.Overlap(network2))
127	            {
128	                result.Add(current);
129	                continue;
130	            }
131	            
132	            // If hole completely contains current, skip it
133	            if (network2.Contains(current))
134	            {
135	                continue;
136	            }
137	            
138	            // If current is same size or smaller than hole and overlaps, we need to split
139	            var split = current.Subnet((byte)(current.Cidr + 1));
140	            var leftHalf = split[0];
141	            var rightHalf = split[1];
142	            
143	            queue.Enqueue(leftHalf);
144	            queue.Enqueue(rightHalf);
145	        }
146	        
147	        return result.OrderBy(n => n.ipaddress).ToList();
